const data = $('Parse Analysis').first().json;
const raw = $input.first().json;

let content =
  (typeof raw.text === 'string' && raw.text) ||
  (raw.message && typeof raw.message.content === 'string' && raw.message.content) ||
  (raw.response && typeof raw.response === 'string' && raw.response) ||
  '';

if (!content && typeof raw === 'object') {
  content = JSON.stringify(raw);
}

content = String(content)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const firstBrace = content.indexOf('{');
const lastBrace = content.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  content = content.slice(firstBrace, lastBrace + 1);
}

let replies;
try {
  replies = JSON.parse(content);
} catch (e) {
  replies = { official: content, semi: content, casual: content };
}

const official = (replies.official || '—').trim();
const semi     = (replies.semi     || '—').trim();
const casual   = (replies.casual   || '—').trim();

/* ---------- Language & direction ---------- */
const isArabic = (data.analysis && data.analysis.language === 'ar') || data.lang === 'ar';
const dir = isArabic ? 'rtl' : 'ltr';
const align = isArabic ? 'right' : 'left';
const side = isArabic ? 'right' : 'left';

/* ---------- Helpers ---------- */
const esc = (s) => String(s)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const nl2br = (s) => esc(s).replace(/\n/g, '<br/>');

/* ---------- Labels ---------- */
const L = isArabic ? {
  header: '📬 تحليل الإيميل',
  from: 'من:', subject: 'الموضوع:', category: 'التصنيف:',
  urgency: 'الأولوية:', sentiment: 'المشاعر:', summary: 'ملخص سريع',
  official: '🏛 الرد الرسمي', semi: '✍️ الرد شبه الرسمي', casual: '💬 الرد العادي',
  footer: 'تم إنشاء هذه الردود تلقائيًا بواسطة Smart Email Responder.'
} : {
  header: '📬 Email Analysis',
  from: 'From:', subject: 'Subject:', category: 'Category:',
  urgency: 'Urgency:', sentiment: 'Sentiment:', summary: 'Quick summary',
  official: '🏛 Official Reply', semi: '✍️ Semi-formal Reply', casual: '💬 Casual Reply',
  footer: 'These replies were generated automatically by Smart Email Responder.'
};

/* ---------- Email subject ---------- */
const emailSubject = 'Re: ' + (data.subject || '—') +
  (isArabic ? ' — ردود مقترحة' : ' — Suggested Replies');

/* ---------- Email HTML (responsive) ---------- */
const emailBody = `<!DOCTYPE html>
<html dir="${dir}" lang="${isArabic ? 'ar' : 'en'}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta http-equiv="X-UA-Compatible" content="IE=edge">
<title>${esc(emailSubject)}</title>
<style>
  /* ====== Reset (email-safe) ====== */
  body, table, td, p, div, h1, h2, h3, span, a {
    margin: 0; padding: 0; border: 0; outline: 0;
    font-size: 100%; vertical-align: baseline; background: transparent;
  }
  body { width: 100% !important; height: 100% !important; }
  table { border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
  img { border: 0; line-height: 100%; outline: none; text-decoration: none; -ms-interpolation-mode: bicubic; }

  /* ====== Base ====== */
  body {
    background-color: #f6f5f1;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'IBM Plex Sans Arabic', Tahoma, Arial, sans-serif;
    line-height: 1.7;
    color: #1b1d23;
    -webkit-text-size-adjust: 100%;
    -ms-text-size-adjust: 100%;
  }
  .email-wrapper {
    width: 100%;
    background-color: #f6f5f1;
    padding: 24px 12px;
    direction: ${dir};
  }
  .email-container {
    width: 600px;
    max-width: 600px;
    background-color: #ffffff;
    border: 1px solid #e4e6eb;
    border-radius: 14px;
    overflow: hidden;
  }
  .px {
    padding-left: 28px;
    padding-right: 28px;
  }
  .title-lg {
    font-size: 20px;
    font-weight: 700;
    color: #2f6b5f;
    line-height: 1.4;
  }
  .body-text {
    font-size: 14px;
    line-height: 1.8;
    color: #1b1d23;
    word-break: break-word;
    overflow-wrap: anywhere;
    -webkit-hyphens: auto;
    hyphens: auto;
  }
  .info-label {
    width: 120px;
    color: #8a8f9a;
    font-size: 13px;
    vertical-align: top;
  }
  .info-value {
    color: #1b1d23;
    font-size: 13.5px;
    vertical-align: top;
    word-break: break-word;
  }
  .summary-box {
    background-color: #fbfbfa;
    border: 1px solid #e4e6eb;
    border-radius: 12px;
    padding: 14px 16px;
  }
  .reply-box {
    border-radius: 12px;
    padding: 14px 16px;
  }
  .reply-heading {
    font-size: 15px;
    font-weight: 700;
    margin-bottom: 8px;
  }
  .reply-official-box  { background-color: #eef4fb; border-${side}: 3px solid #264b7c; }
  .reply-semi-box      { background-color: #fdf3e7; border-${side}: 3px solid #8a5a2b; }
  .reply-casual-box    { background-color: #f0edfa; border-${side}: 3px solid #5a4a8a; }
  .reply-official-head { color: #264b7c; }
  .reply-semi-head     { color: #8a5a2b; }
  .reply-casual-head   { color: #5a4a8a; }
  .footer-text {
    font-size: 11.5px;
    color: #8a8f9a;
    text-align: center;
  }
  .divider-space { height: 20px; line-height: 20px; font-size: 0; }

  /* ====== Mobile ====== */
  @media only screen and (max-width: 620px) {
    .email-wrapper { padding: 14px 8px !important; }
    .email-container {
      width: 100% !important;
      max-width: 100% !important;
      border-radius: 12px !important;
    }
    .px {
      padding-left: 16px !important;
      padding-right: 16px !important;
    }
    .title-lg { font-size: 17px !important; }
    .body-text { font-size: 13.5px !important; line-height: 1.75 !important; }
    .info-label { width: 80px !important; font-size: 12px !important; }
    .info-value { font-size: 12.5px !important; }
    .summary-box { padding: 12px 13px !important; }
    .reply-box { padding: 12px 13px !important; }
    .reply-heading { font-size: 14px !important; }
    .footer-text { font-size: 11px !important; }
    .divider-space { height: 14px !important; line-height: 14px !important; }
  }
</style>
</head>
<body>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f6f5f1;">
  <tr>
    <td class="email-wrapper" align="center" valign="top">

      <table role="presentation" class="email-container" width="600" cellpadding="0" cellspacing="0" border="0" align="center" style="background-color:#ffffff;border:1px solid #e4e6eb;border-radius:14px;">

        <!-- ===== Header ===== -->
        <tr>
          <td class="px" style="padding-top:26px;padding-bottom:14px;text-align:${align};">
            <h2 class="title-lg" style="margin:0;">${L.header}</h2>
          </td>
        </tr>

        <!-- ===== Info table ===== -->
        <tr>
          <td class="px" style="padding-bottom:20px;text-align:${align};">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;">
              <tr>
                <td class="info-label" style="padding:5px 0;text-align:${align};">${L.from}</td>
                <td class="info-value" style="padding:5px 0;text-align:${align};"><b>${esc(data.from)}</b></td>
              </tr>
              <tr>
                <td class="info-label" style="padding:5px 0;text-align:${align};">${L.subject}</td>
                <td class="info-value" style="padding:5px 0;text-align:${align};">${esc(data.subject)}</td>
              </tr>
              <tr>
                <td class="info-label" style="padding:5px 0;text-align:${align};">${L.category}</td>
                <td class="info-value" style="padding:5px 0;text-align:${align};">${esc(data.analysis.category)}</td>
              </tr>
              <tr>
                <td class="info-label" style="padding:5px 0;text-align:${align};">${L.urgency}</td>
                <td class="info-value" style="padding:5px 0;text-align:${align};">${esc(data.analysis.urgency)}</td>
              </tr>
              <tr>
                <td class="info-label" style="padding:5px 0;text-align:${align};">${L.sentiment}</td>
                <td class="info-value" style="padding:5px 0;text-align:${align};">${esc(data.analysis.sentiment)}</td>
              </tr>
            </table>
          </td>
        </tr>

        <!-- ===== Summary ===== -->
        <tr>
          <td class="px" style="padding-bottom:22px;">
            <div class="summary-box" style="text-align:${align};">
              <b style="display:block;margin-bottom:6px;color:#1b1d23;font-size:13.5px;">${L.summary}</b>
              <span class="body-text" style="color:#4b4f5a;display:block;">${esc(data.analysis.summary)}</span>
            </div>
          </td>
        </tr>

        <!-- ===== Official Reply ===== -->
        <tr>
          <td class="px" style="padding-bottom:8px;text-align:${align};">
            <h3 class="reply-heading reply-official-head" style="margin:0;">${L.official}</h3>
          </td>
        </tr>
        <tr>
          <td class="px" style="padding-bottom:22px;">
            <div class="reply-box reply-official-box body-text" style="text-align:${align};">
              ${nl2br(official)}
            </div>
          </td>
        </tr>

        <!-- ===== Semi-formal Reply ===== -->
        <tr>
          <td class="px" style="padding-bottom:8px;text-align:${align};">
            <h3 class="reply-heading reply-semi-head" style="margin:0;">${L.semi}</h3>
          </td>
        </tr>
        <tr>
          <td class="px" style="padding-bottom:22px;">
            <div class="reply-box reply-semi-box body-text" style="text-align:${align};">
              ${nl2br(semi)}
            </div>
          </td>
        </tr>

        <!-- ===== Casual Reply ===== -->
        <tr>
          <td class="px" style="padding-bottom:8px;text-align:${align};">
            <h3 class="reply-heading reply-casual-head" style="margin:0;">${L.casual}</h3>
          </td>
        </tr>
        <tr>
          <td class="px" style="padding-bottom:24px;">
            <div class="reply-box reply-casual-box body-text" style="text-align:${align};">
              ${nl2br(casual)}
            </div>
          </td>
        </tr>

        <!-- ===== Footer ===== -->
        <tr>
          <td class="px" style="padding-bottom:24px;">
            <p class="footer-text">${L.footer}</p>
          </td>
        </tr>

      </table>

    </td>
  </tr>
</table>
</body>
</html>`.trim();

return [{
  json: {
    success: true,
    userName: data.userName,
    userEmail: data.userEmail,
    from: data.from,
    subject: data.subject,
    analysis: data.analysis,
    replies: { official, semi, casual },
    emailSubject,
    emailBody,
    generatedAt: new Date().toISOString()
  }
}];

const prep = $('Prepare Email').first().json;
const raw = $input.first().json;

let content =
  (typeof raw.text === 'string' && raw.text) ||
  (raw.message && typeof raw.message.content === 'string' && raw.message.content) ||
  (raw.response && typeof raw.response === 'string' && raw.response) ||
  '';

if (!content && typeof raw === 'object') {
  content = JSON.stringify(raw);
}

content = String(content)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/```\s*$/i, '')
  .trim();

const firstBrace = content.indexOf('{');
const lastBrace = content.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
  content = content.slice(firstBrace, lastBrace + 1);
}

let analysis;
try {
  analysis = JSON.parse(content);
} catch (e) {
  analysis = {
    category: 'other',
    sentiment: 'neutral',
    urgency: 'medium',
    language: prep.lang === 'ar' ? 'ar' : 'en',
    summary: 'Could not parse analysis output.'
  };
}

return [{ json: { ...prep, analysis } }];

const body = $input.first().json.body || $input.first().json;
const from = (body.from || '').trim();
const subject = (body.subject || '').trim();
const text = (body.text || '').trim();
const userName = (body.userName || '').trim();
const userEmail = (body.userEmail || '').trim();
const lang = body.lang === 'en' ? 'en' : 'ar';

if (!text || text.length < 3) {
  throw new Error('Email body is required (min 3 chars).');
}
if (!userName) {
  throw new Error('userName is required.');
}
if (!userEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(userEmail)) {
  throw new Error('A valid userEmail is required.');
}

return [{ json: { from, subject, text, userName, userEmail, lang } }];

